    open: sumDues(splits.map((s) => s.open)),
    upTo30: sumDues(splits.map((s) => s.aged.upTo30)),
    upTo60: sumDues(splits.map((s) => s.aged.upTo60)),
    over60: sumDues(splits.map((s) => s.aged.over60)),
