export function ownPart(c: Claim, due: string | null): string | null {
  if (due === null || (c.shares ?? []).length === 0) return due;
  return formatCents((c.shares ?? []).reduce((t, s) => t - hundredths(sharePart(due, s.share)), hundredths(due)));
}

